// Generated by Bug2PR: reproduces a bug from a screen recording.
// Expected behaviour: Editing the Movies Gift payment from 3.29 to 50.00 should recalculate the running Balance column for that row and subsequent rows to reflect the new account total of 3,867.24
import { expect, test } from '@playwright/test';

test("bug2pr: actual-8475-running-balance", async ({ page }) => {
  let before = '';
  await page.setViewportSize({"width":1280,"height":900});
  await test.step('reproduce', async () => {
    await page.goto("/");
    await page.getByRole("button", { name: "Create test file", exact: true }).click();
    await page.getByRole("link", { name: "Bank of America", exact: false }).nth(0).click();
    await page.getByTestId("transaction-table").first().waitFor();
    await page.getByRole("button", { name: "Account menu", exact: true }).click();
    await page.getByRole("button", { name: "Show balance chart", exact: true }).click();
    await page.getByRole("button", { name: "Account menu", exact: true }).click();
    await page.getByRole("button", { name: "Hide balance chart", exact: true }).click();
    await page.getByRole("button", { name: "Account menu", exact: true }).click();
    await page.getByRole("button", { name: "Show balance chart", exact: true }).click();
    await page.getByRole("button", { name: "Account menu", exact: true }).click();
    await page.getByRole("button", { name: "Hide balance chart", exact: true }).click();
    await page.getByRole("button", { name: "Account menu", exact: true }).click();
    await page.getByRole("button", { name: "Show running balance", exact: true }).click();
    before = (await page.getByTestId("row").filter({ hasText: "Movies" }).first().getByTestId("balance").first().innerText()).trim();
    await page.getByTestId("row").filter({ hasText: "Movies" }).first().getByTestId("debit").click();
    await page.keyboard.type("50.00");
    await page.keyboard.press("Enter");
  });
  await test.step("expected: Editing the Movies Gift payment to 50.00 recalculates its running Balance column to reflect the new total", async () => {
    await expect(page.getByTestId("row").filter({ hasText: "Movies" }).first().getByTestId("balance").filter({ visible: true }).first()).not.toHaveText(before);
  });
  void before;
});
